var ITEMS=[["Pennsylvania: history overview","Pennsylvania: the Keystone State, admitted 1787 (2nd); capital Harrisburg."], ["state","Pennsylvania"], ["nickname","Keystone State"], ["admitted","1787 (2nd)"], ["capital","Harrisburg"]];
function ask(n){var out=[],seen={};n=Math.min(n,ITEMS.length);for(var k=0;k<n;k++){var it=ITEMS[(Math.random()*ITEMS.length)|0];out.push("Q"+(k+1)+": "+it[0]+"\nA"+(k+1)+": "+it[1]);}return out.join("\n\n");}
